export default function status({ body, projectId, previous }) {
  const { id, status, downloads } = body ?? {};
  if (id !== projectId) throw Error("Project ID mismatch");
  const count = previous == null ? 1 : previous.count + 1;
  if (!Number.isInteger(count) || count > 60)
    throw Error("Polling timed out for project " + projectId);
  if (status === "error" || status === "canceled")
    throw Error("Generation " + status + " for project " + projectId);
  if (status === "complete") {
    if (!Array.isArray(downloads) || !downloads[0] || typeof downloads[0].url !== "string")
      throw Error("Missing download for project " + projectId);
    return { state: { count }, done: true, url: downloads[0].url };
  }
  if (!["draft", "queued", "rendering"].includes(status))
    throw Error("Unexpected status for project " + projectId);
  if (count === 60) throw Error("Polling timed out for project " + projectId);
  return { state: { count }, done: false, url: "" };
}

