import { Buffer } from "node:buffer";
export default async function download({ url, id }, context) {
  if (typeof url !== "string" || !/^https:\/\//.test(url))
    throw Error("Invalid video URL for project " + id);
  const r = await context.fetch(url, { method: "GET" });
  if (!r.ok) throw Error("Download failed for project " + id);
  const b = Buffer.from(await r.arrayBuffer());
  if (b.length < 12 || b.subarray(4, 8).toString() !== "ftyp")
    throw Error("Invalid MP4 for project " + id);
  const video = await context.artifact.put(b, { name: "video.mp4", mediaType: "video/mp4" });
  return { video, url, id };
}
